import{_ as e,o as r,c as t,ai as l}from"./chunks/framework.ETupdKIa.js";const c=JSON.parse('{"title":"パスワード保管方法","description":"","frontmatter":{},"headers":[],"relativePath":"til/Auth/20240611_パスワード保管方法.md","filePath":"til/Auth/20240611_パスワード保管方法.md"}'),i={name:"til/Auth/20240611_パスワード保管方法.md"};function s(p,a,_,h,n,o){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="パスワード保管方法" tabindex="-1">パスワード保管方法 <a class="header-anchor" href="#パスワード保管方法" aria-label="Permalink to “パスワード保管方法”">​</a></h1><h2 id="一番ダメなパスワード保管方法" tabindex="-1">一番ダメなパスワード保管方法 <a class="header-anchor" href="#一番ダメなパスワード保管方法" aria-label="Permalink to “一番ダメなパスワード保管方法”">​</a></h2><p>DBに平文でパスワードを保管すること。</p><h2 id="じゃあハッシュ化して保管すれば十分か" tabindex="-1">じゃあハッシュ化して保管すれば十分か <a class="header-anchor" href="#じゃあハッシュ化して保管すれば十分か" aria-label="Permalink to “じゃあハッシュ化して保管すれば十分か”">​</a></h2><p>不十分。単にハッシュ化しただけだと、単純なパスワードの場合に簡単にパスワードを特定されてしまう。 流れ</p><ul><li>攻撃者がDBまで侵入し、パスワードを奪う。</li><li>奪ったパスワードはハッシュ化されているが、そのうちいくつかが重複していることに気づく。</li><li>複数ユーザーでパスワードが一致していることから、ハッシュ化前のパスワードは単純なパスワード(Ex.&quot;password&quot;)である可能性が高い。</li><li>単純なパスワードとして知られる文字列をハッシュ化してみたら、奪ったパスワードと一致。パスワード割り出しに成功。</li></ul><h2 id="じゃあどうすれば良いのか" tabindex="-1">じゃあどうすれば良いのか <a class="header-anchor" href="#じゃあどうすれば良いのか" aria-label="Permalink to “じゃあどうすれば良いのか”">​</a></h2><p>パスワードにユーザー毎に異なる文字列(salt)を連結し、それをハッシュ化してDBに保管する。 こうすることで、DBに保管されるパスワード情報(pass+saltをハッシュ化した文字列)が一致することがなくなる。 DBへの保管方法は、ハッシュ化アルゴリズム(md5など)+ソルト+ハッシュ値をユーザー毎に持たせるのが一般的。</p><h2 id="もっと良い方法はある" tabindex="-1">もっと良い方法はある？ <a class="header-anchor" href="#もっと良い方法はある" aria-label="Permalink to “もっと良い方法はある？”">​</a></h2><p>DBへの侵入を前提とすると、↑の方法だと攻撃者はsaltも入手できてしまう。 よりパスワードの機密性を高めるなら、DBとは別の機密性の高いファイルにpepperと呼ばれる文字列を保管しておき、 pass+salt+pepperをハッシュ化してDBにパスワード情報として保管しておくと良い。 ハッシュ値を奪えてもpepperを知らなければ元のパスワードを割り出すのは困難。</p><h2 id="とは言ったけど・・・" tabindex="-1">とは言ったけど・・・ <a class="header-anchor" href="#とは言ったけど・・・" aria-label="Permalink to “とは言ったけど・・・”">​</a></h2><p>仮にpass+salt+pepperでパスワードを保管したとしても、攻撃者にパスワードを割り出される可能性を0にはできない。 あくまでもこのような対策は、攻撃者がパスワードを割り出すことを最大限困難にすることを目的としている。 そうすれば、パスワード漏洩を検知した際に、できることが増えてくる。</p>',12)])])}const m=e(i,[["render",s]]);export{c as __pageData,m as default};
